[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ============================================
   DESIGN TOKENS
   ============================================ */
:root {
  /* OKLCH Color Palette */
  --bg-primary: oklch(10% 0.005 265);
  --bg-surface: oklch(16% 0.006 265);
  --bg-surface-hover: oklch(22% 0.008 265);
  --bg-elevated: oklch(20% 0.008 265);
  --text-primary: oklch(97% 0.005 265);
  --text-secondary: oklch(68% 0.02 265);
  --text-muted: oklch(52% 0.015 265);
  --accent-blue: oklch(62% 0.2 265);
  --accent-blue-hover: oklch(68% 0.22 265);
  --accent-amber: oklch(76% 0.16 75);
  --accent-amber-hover: oklch(80% 0.18 75);
  --border-subtle: oklch(24% 0.01 265);
  --border-medium: oklch(32% 0.015 265);

  /* Spacing (8px base) */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 16px;
  --sp-4: 24px;
  --sp-5: 32px;
  --sp-6: 48px;
  --sp-7: 64px;
  --sp-8: 96px;
  --sp-9: 128px;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --fs-hero: clamp(40px, 6vw, 72px);
  --fs-h2: clamp(32px, 4vw, 48px);
  --fs-h3: clamp(20px, 2.5vw, 28px);
  --fs-h4: clamp(16px, 1.5vw, 20px);
  --fs-body: 16px;
  --fs-small: 14px;
  --fs-xs: 12px;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 200ms;
  --duration-normal: 350ms;
  --duration-slow: 600ms;

  /* Layout */
  --max-width: 1280px;
  --nav-height: 72px;
}

/* ============================================
   RESET & BASE
   ============================================ */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: var(--fs-body);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

ul, ol { list-style: none; }
img { max-width: 100%; display: block; }

:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}

/* ============================================
   UTILITY
   ============================================ */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-5);
}

.section-gap {
  padding: var(--sp-9) 0;
}

.accent-text {
  color: var(--accent-blue);
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-5);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: var(--fs-small);
  letter-spacing: 0.02em;
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-blue);
  color: oklch(10% 0.01 265);
}

.btn-primary:hover {
  background: var(--accent-blue-hover);
  transform: translateY(-1px);
}

.btn-outline {
  border: 1px solid var(--border-medium);
  color: var(--text-primary);
}

.btn-outline:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.btn-amber {
  background: var(--accent-amber);
  color: oklch(10% 0.01 265);
}

.btn-amber:hover {
  background: var(--accent-amber-hover);
  transform: translateY(-1px);
}

.section-label {
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-blue);
  margin-bottom: var(--sp-4);
}

.section-title {
  font-size: var(--fs-h2);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.section-subtitle {
  font-size: var(--fs-h4);
  color: var(--text-secondary);
  line-height: 1.5;
  max-width: 680px;
  margin-top: var(--sp-4);
}

/* ============================================
   NAVIGATION
   ============================================ */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--nav-height);
  background: oklch(10% 0.005 265 / 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid oklch(24% 0.01 265 / 0.5);
  transition: background var(--duration-fast);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--sp-5);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  flex-shrink: 0;
}

.nav-brand span {
  color: var(--accent-blue);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--sp-5);
}

.nav-links a {
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--duration-fast);
  white-space: nowrap;
}

.nav-links a:hover {
  color: var(--text-primary);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: var(--sp-4);
}

/* Language Selector */
.lang-selector {
  position: relative;
}

.lang-toggle {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-secondary);
  padding: var(--sp-2) var(--sp-3);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  transition: all var(--duration-fast);
}

.lang-toggle:hover {
  border-color: var(--border-medium);
  color: var(--text-primary);
}

.lang-toggle svg {
  width: 14px;
  height: 14px;
  transition: transform var(--duration-fast);
}

.lang-selector.open .lang-toggle svg {
  transform: rotate(180deg);
}

.lang-dropdown {
  position: absolute;
  top: calc(100% + var(--sp-2));
  right: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: var(--sp-2) 0;
  min-width: 160px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--duration-fast) var(--ease-out);
}

.lang-selector.open .lang-dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.lang-option {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-4);
  font-size: var(--fs-small);
  color: var(--text-secondary);
  width: 100%;
  transition: all var(--duration-fast);
}

.lang-option:hover {
  background: var(--bg-surface-hover);
  color: var(--text-primary);
}

.lang-option.active {
  color: var(--accent-blue);
}

/* Hamburger */
.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--sp-2);
}

.nav-hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-primary);
  border-radius: 1px;
  transition: all var(--duration-fast);
}

.nav-hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-hamburger.active span:nth-child(2) {
  opacity: 0;
}

.nav-hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 999;
  padding: var(--sp-6);
  opacity: 0;
  transform: translateY(-10px);
  transition: all var(--duration-normal) var(--ease-out);
}

.mobile-nav.open {
  opacity: 1;
  transform: translateY(0);
}

.mobile-nav a {
  display: block;
  font-size: var(--fs-h3);
  font-weight: 600;
  color: var(--text-secondary);
  padding: var(--sp-3) 0;
  transition: color var(--duration-fast);
}

.mobile-nav a:hover {
  color: var(--text-primary);
}

@media (max-width: 1023px) {
  .nav-links { display: none; }
  .nav-hamburger { display: flex; }
  .mobile-nav { display: block; }
}

/* ============================================
   HERO CAROUSEL
   ============================================ */
.hero {
  position: relative;
  min-height: calc(100vh - var(--nav-height));
  margin-top: var(--nav-height);
  overflow: hidden;
}

.hero-track {
  display: flex;
  transition: transform var(--duration-slow) var(--ease-in-out);
  height: 100%;
}

.hero-slide {
  min-width: 100%;
  position: relative;
  display: flex;
  align-items: center;
  min-height: calc(100vh - var(--nav-height));
}

.hero-slide-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-slide-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(10% 0.005 265 / 0.92), oklch(10% 0.005 265 / 0.6));
}

.hero-slide-content {
  position: relative;
  z-index: 1;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--sp-8) var(--sp-5);
  width: 100%;
}

.hero-slide-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-blue);
  margin-bottom: var(--sp-5);
}

.hero-slide-tag::before {
  content: '';
  width: 24px;
  height: 2px;
  background: var(--accent-blue);
}

.hero-slide-title {
  font-size: var(--fs-hero);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.03em;
  max-width: 800px;
  margin-bottom: var(--sp-5);
}

.hero-slide-desc {
  font-size: var(--fs-h4);
  color: var(--text-secondary);
  max-width: 560px;
  line-height: 1.5;
  margin-bottom: var(--sp-6);
}

/* Hero Navigation */
.hero-nav {
  position: absolute;
  bottom: var(--sp-7);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  z-index: 2;
}

.hero-dot {
  width: 32px;
  height: 3px;
  border-radius: 2px;
  background: oklch(40% 0.01 265);
  transition: all var(--duration-normal) var(--ease-out);
  cursor: pointer;
}

.hero-dot.active {
  width: 48px;
  background: var(--accent-blue);
}

.hero-arrows {
  position: absolute;
  bottom: var(--sp-7);
  right: var(--sp-5);
  display: flex;
  gap: var(--sp-2);
  z-index: 2;
}

.hero-arrow {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-medium);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  color: var(--text-secondary);
}

.hero-arrow:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.hero-arrow svg {
  width: 18px;
  height: 18px;
}

/* Placeholder backgrounds for hero slides */
.hero-slide:nth-child(1) .hero-slide-bg {
  background: linear-gradient(135deg, oklch(25% 0.06 280), oklch(15% 0.04 240));
}

.hero-slide:nth-child(2) .hero-slide-bg {
  background: linear-gradient(135deg, oklch(22% 0.05 200), oklch(18% 0.04 260));
}

.hero-slide:nth-child(3) .hero-slide-bg {
  background: linear-gradient(135deg, oklch(20% 0.06 300), oklch(14% 0.03 220));
}

.hero-slide:nth-child(4) .hero-slide-bg {
  background: linear-gradient(135deg, oklch(23% 0.05 180), oklch(16% 0.04 250));
}

.hero-slide:nth-child(5) .hero-slide-bg {
  background: linear-gradient(135deg, oklch(21% 0.06 320), oklch(15% 0.04 240));
}

/* ============================================
   TEAM CAROUSEL
   ============================================ */
.team {
  background: var(--bg-primary);
}

.team-header {
  margin-bottom: var(--sp-7);
}

/* Region Tabs */
.region-tabs {
  display: flex;
  gap: var(--sp-1);
  margin-bottom: var(--sp-6);
  border-bottom: 1px solid var(--border-subtle);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.region-tab {
  padding: var(--sp-3) var(--sp-4);
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  transition: all var(--duration-fast);
  white-space: nowrap;
  margin-bottom: -1px;
}

.region-tab:hover {
  color: var(--text-secondary);
}

.region-tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

/* Team Cards Carousel */
.team-carousel-wrapper {
  position: relative;
  overflow: hidden;
}

.team-carousel {
  display: flex;
  gap: var(--sp-5);
  transition: transform var(--duration-normal) var(--ease-out);
  padding-bottom: var(--sp-4);
}

.team-card {
  min-width: 340px;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  flex-shrink: 0;
  transition: border-color var(--duration-fast);
}

.team-card:hover {
  border-color: var(--border-medium);
}

.team-card-photo {
  width: 100%;
  height: 240px;
  position: relative;
  overflow: hidden;
}

.team-card-photo-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  font-weight: 700;
  color: oklch(30% 0.01 265);
}

.team-card:nth-child(odd) .team-card-photo-placeholder {
  background: linear-gradient(135deg, oklch(28% 0.03 260), oklch(22% 0.05 280));
}

.team-card:nth-child(even) .team-card-photo-placeholder {
  background: linear-gradient(135deg, oklch(26% 0.04 290), oklch(20% 0.03 250));
}

.team-card-body {
  padding: var(--sp-5);
}

.team-card-name {
  font-size: var(--fs-h4);
  font-weight: 700;
  margin-bottom: var(--sp-1);
}

.team-card-title {
  font-size: var(--fs-small);
  color: var(--accent-blue);
  font-weight: 500;
  margin-bottom: var(--sp-3);
}

.team-card-quote {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.6;
  font-style: italic;
  margin-bottom: var(--sp-4);
  position: relative;
  padding-left: var(--sp-3);
  border-left: 2px solid var(--accent-blue);
}

.team-card-cta {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-xs);
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: color var(--duration-fast);
}

.team-card-cta:hover {
  color: var(--accent-blue);
}

.team-card-cta svg {
  width: 14px;
  height: 14px;
  transition: transform var(--duration-fast);
}

.team-card-cta:hover svg {
  transform: translateX(3px);
}

/* Team Carousel Controls */
.team-carousel-nav {
  display: flex;
  gap: var(--sp-2);
  margin-top: var(--sp-5);
}

.team-carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--duration-fast);
  color: var(--text-secondary);
}

.team-carousel-btn:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue);
}

.team-carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.team-carousel-btn:disabled:hover {
  border-color: var(--border-subtle);
  color: var(--text-secondary);
}

.team-carousel-btn svg {
  width: 16px;
  height: 16px;
}

/* ============================================
   WORK SHOWCASE
   ============================================ */
.work {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.work-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: var(--sp-6);
  gap: var(--sp-5);
  flex-wrap: wrap;
}

.work-scroll-container {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-snap-type: x mandatory;
  padding-bottom: var(--sp-3);
}

.work-scroll-container::-webkit-scrollbar {
  display: none;
}

.work-cards {
  display: flex;
  gap: var(--sp-5);
}

.work-card {
  min-width: 360px;
  max-width: 420px;
  flex-shrink: 0;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--duration-fast) var(--ease-out);
}

.work-card:hover {
  border-color: var(--border-medium);
  transform: translateY(-4px);
}

.work-card-img {
  width: 100%;
  height: 220px;
  position: relative;
  overflow: hidden;
}

.work-card-img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.work-card:nth-child(1) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(30% 0.06 180), oklch(20% 0.04 240)); }
.work-card:nth-child(2) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(28% 0.05 300), oklch(18% 0.04 260)); }
.work-card:nth-child(3) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(26% 0.06 140), oklch(22% 0.04 200)); }
.work-card:nth-child(4) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(32% 0.05 250), oklch(16% 0.04 300)); }
.work-card:nth-child(5) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(24% 0.06 320), oklch(20% 0.04 260)); }
.work-card:nth-child(6) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(28% 0.05 160), oklch(22% 0.04 220)); }
.work-card:nth-child(7) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(30% 0.04 280), oklch(18% 0.05 200)); }
.work-card:nth-child(8) .work-card-img-placeholder { background: linear-gradient(135deg, oklch(26% 0.06 220), oklch(20% 0.03 180)); }

.work-card-img-text {
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(50% 0.03 265);
}

.work-card-body {
  padding: var(--sp-5);
}

.work-card-client {
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent-blue);
  margin-bottom: var(--sp-2);
}

.work-card-title {
  font-size: var(--fs-h4);
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: var(--sp-3);
}

.work-card-quote {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.5;
  font-style: italic;
}

.work-card-link {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--accent-blue);
  margin-top: var(--sp-4);
  transition: gap var(--duration-fast);
}

.work-card-link:hover {
  gap: var(--sp-3);
}

/* ============================================
   CTA BANNER
   ============================================ */
.cta-banner {
  position: relative;
  overflow: hidden;
}

.cta-banner-inner {
  background: linear-gradient(135deg, oklch(25% 0.08 265), oklch(18% 0.06 290));
  border-radius: var(--radius-lg);
  padding: var(--sp-8) var(--sp-7);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner-inner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, oklch(62% 0.2 265 / 0.15), transparent 70%);
  border-radius: 50%;
}

.cta-banner-inner::after {
  content: '';
  position: absolute;
  bottom: -40%;
  left: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, oklch(76% 0.16 75 / 0.1), transparent 70%);
  border-radius: 50%;
}

.cta-banner-content {
  position: relative;
  z-index: 1;
}

.cta-banner h2 {
  font-size: var(--fs-h2);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: var(--sp-4);
}

.cta-banner p {
  font-size: var(--fs-h4);
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto var(--sp-6);
  line-height: 1.5;
}

/* ============================================
   HOW WE WORK
   ============================================ */
.how {
  background: var(--bg-primary);
}

.how-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-8);
  align-items: center;
}

.how-visual {
  position: relative;
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.how-visual-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, oklch(22% 0.06 270), oklch(16% 0.04 290), oklch(20% 0.05 250));
  display: flex;
  align-items: center;
  justify-content: center;
}

.how-visual-text {
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(40% 0.03 265);
}

.how-content {
  max-width: 520px;
}

.how-content .section-label {
  margin-bottom: var(--sp-3);
}

.how-content h2 {
  font-size: var(--fs-h2);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: var(--sp-4);
}

.how-content p {
  font-size: var(--fs-body);
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--sp-6);
}

/* ============================================
   LATEST INSIGHTS
   ============================================ */
.insights {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.insights-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: var(--sp-6);
  gap: var(--sp-5);
  flex-wrap: wrap;
}

.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--sp-5);
}

.insight-card {
  background: var(--bg-primary);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all var(--duration-fast) var(--ease-out);
}

.insight-card:hover {
  border-color: var(--border-medium);
  transform: translateY(-2px);
}

.insight-card-img {
  width: 100%;
  height: 160px;
  position: relative;
  overflow: hidden;
}

.insight-card-img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.insight-card:nth-child(1) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(24% 0.05 280), oklch(18% 0.04 240)); }
.insight-card:nth-child(2) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(26% 0.04 300), oklch(20% 0.05 260)); }
.insight-card:nth-child(3) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(22% 0.06 200), oklch(16% 0.03 240)); }
.insight-card:nth-child(4) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(28% 0.05 260), oklch(18% 0.04 300)); }
.insight-card:nth-child(5) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(24% 0.04 320), oklch(20% 0.05 280)); }
.insight-card:nth-child(6) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(26% 0.06 220), oklch(16% 0.03 200)); }
.insight-card:nth-child(7) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(22% 0.05 180), oklch(18% 0.04 260)); }
.insight-card:nth-child(8) .insight-card-img-placeholder { background: linear-gradient(135deg, oklch(28% 0.04 290), oklch(20% 0.05 240)); }

.insight-card-img-text {
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(45% 0.03 265);
}

.insight-card-body {
  padding: var(--sp-4) var(--sp-5) var(--sp-5);
}

.insight-card-type {
  display: inline-block;
  font-size: var(--fs-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-amber);
  margin-bottom: var(--sp-2);
}

.insight-card-type.podcast {
  color: oklch(70% 0.18 145);
}

.insight-card-type.report {
  color: oklch(68% 0.16 300);
}

.insight-card-title {
  font-size: var(--fs-body);
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--sp-3);
}

.insight-card-link {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--accent-blue);
  transition: opacity var(--duration-fast);
}

.insight-card-link:hover {
  opacity: 0.8;
}

/* ============================================
   PRINCIPLES
   ============================================ */
.principles {
  background: var(--bg-primary);
}

.principles-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--sp-5);
  margin-top: var(--sp-7);
}

.principle-card {
  padding: var(--sp-6);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  transition: all var(--duration-fast) var(--ease-out);
  position: relative;
  overflow: hidden;
}

.principle-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  background: var(--accent-blue);
  opacity: 0;
  transition: opacity var(--duration-fast);
}

.principle-card:hover {
  border-color: var(--border-medium);
}

.principle-card:hover::before {
  opacity: 1;
}

.principle-number {
  font-size: var(--fs-h2);
  font-weight: 800;
  color: oklch(20% 0.01 265);
  line-height: 1;
  margin-bottom: var(--sp-4);
}

.principle-card:hover .principle-number {
  color: oklch(30% 0.06 265);
}

.principle-title {
  font-size: var(--fs-h3);
  font-weight: 700;
  margin-bottom: var(--sp-3);
  line-height: 1.2;
}

.principle-desc {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ============================================
   FOOTER
   ============================================ */
.footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
}

.footer-ctas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--sp-5);
  margin-bottom: var(--sp-8);
}

.footer-cta-card {
  padding: var(--sp-6);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  transition: border-color var(--duration-fast);
}

.footer-cta-card:hover {
  border-color: var(--border-medium);
}

.footer-cta-card p {
  font-size: var(--fs-h4);
  color: var(--text-secondary);
  line-height: 1.5;
  margin-bottom: var(--sp-4);
}

.footer-cta-card .btn {
  margin-top: var(--sp-2);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--sp-5);
  padding: var(--sp-6) 0;
  border-top: 1px solid var(--border-subtle);
  flex-wrap: wrap;
}

.footer-links {
  display: flex;
  gap: var(--sp-5);
  flex-wrap: wrap;
}

.footer-links a {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  transition: color var(--duration-fast);
}

.footer-links a:hover {
  color: var(--text-primary);
}

.footer-legal {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  display: flex;
  gap: var(--sp-4);
  flex-wrap: wrap;
}

.footer-legal a {
  color: var(--text-muted);
  transition: color var(--duration-fast);
}

.footer-legal a:hover {
  color: var(--text-secondary);
}

.footer-brand {
  font-size: 14px;
  color: var(--text-muted);
}

/* ============================================
   COOKIE CONSENT
   ============================================ */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 2000;
  background: var(--bg-elevated);
  border-top: 1px solid var(--border-subtle);
  padding: var(--sp-5);
  transform: translateY(100%);
  transition: transform var(--duration-normal) var(--ease-out);
}

.cookie-banner.visible {
  transform: translateY(0);
}

.cookie-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-5);
  flex-wrap: wrap;
}

.cookie-text {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  max-width: 600px;
  line-height: 1.5;
}

.cookie-text a {
  color: var(--accent-blue);
  text-decoration: underline;
}

.cookie-actions {
  display: flex;
  gap: var(--sp-3);
  flex-shrink: 0;
}

.cookie-actions .btn {
  font-size: var(--fs-xs);
  padding: var(--sp-2) var(--sp-4);
}

/* Cookie Settings Modal */
.cookie-modal-overlay {
  position: fixed;
  inset: 0;
  background: oklch(10% 0.005 265 / 0.8);
  z-index: 3000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: all var(--duration-fast);
}

.cookie-modal-overlay.visible {
  opacity: 1;
  visibility: visible;
}

.cookie-modal {
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--sp-6);
  max-width: 520px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
  transform: scale(0.95);
  transition: transform var(--duration-fast) var(--ease-out);
}

.cookie-modal-overlay.visible .cookie-modal {
  transform: scale(1);
}

.cookie-modal h3 {
  font-size: var(--fs-h3);
  font-weight: 700;
  margin-bottom: var(--sp-4);
}

.cookie-modal p {
  font-size: var(--fs-small);
  color: var(--text-secondary);
  margin-bottom: var(--sp-5);
  line-height: 1.6;
}

.cookie-option {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--sp-3) 0;
  border-bottom: 1px solid var(--border-subtle);
}

.cookie-option:last-child {
  border-bottom: none;
}

.cookie-option-label {
  font-size: var(--fs-small);
  font-weight: 500;
}

.cookie-option-label span {
  display: block;
  font-size: var(--fs-xs);
  color: var(--text-muted);
  font-weight: 400;
  margin-top: var(--sp-1);
}

/* Toggle Switch */
.toggle {
  position: relative;
  width: 44px;
  height: 24px;
  flex-shrink: 0;
}

.toggle input {
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background: oklch(32% 0.01 265);
  border-radius: 12px;
  transition: background var(--duration-fast);
}

.toggle-slider::before {
  content: '';
  position: absolute;
  height: 18px;
  width: 18px;
  left: 3px;
  bottom: 3px;
  background: var(--text-primary);
  border-radius: 50%;
  transition: transform var(--duration-fast);
}

.toggle input:checked + .toggle-slider {
  background: var(--accent-blue);
}

.toggle input:checked + .toggle-slider::before {
  transform: translateX(20px);
}

.toggle input:disabled + .toggle-slider {
  opacity: 0.5;
  cursor: not-allowed;
}

.cookie-modal-actions {
  display: flex;
  gap: var(--sp-3);
  margin-top: var(--sp-5);
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1023px) {
  .hero-slide-title {
    max-width: 100%;
  }

  .hero-arrows {
    display: none;
  }

  .how-inner {
    grid-template-columns: 1fr;
    gap: var(--sp-6);
  }

  .how-visual {
    aspect-ratio: 16/9;
  }

  .principles-grid {
    grid-template-columns: 1fr;
  }

  .footer-ctas {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
  }

  .team-card {
    min-width: 300px;
  }

  .work-card {
    min-width: 300px;
  }
}

@media (max-width: 639px) {
  :root {
    --sp-9: 80px;
    --sp-8: 64px;
    --sp-7: 48px;
  }

  .hero-slide {
    min-height: auto;
    padding: var(--sp-8) 0;
  }

  .hero-nav {
    bottom: var(--sp-5);
  }

  .hero-slide-content {
    padding: var(--sp-5);
  }

  .team-card {
    min-width: 280px;
  }

  .work-card {
    min-width: 280px;
  }

  .insights-grid {
    grid-template-columns: 1fr;
  }

  .cookie-inner {
    flex-direction: column;
    text-align: center;
  }

  .cookie-actions {
    flex-wrap: wrap;
    justify-content: center;
  }

  .cta-banner-inner {
    padding: var(--sp-6) var(--sp-5);
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  .hero-track {
    transition: none;
  }
}
</style>
