from html.parser import HTMLParser
import sys

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','source','track','wbr'}

    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append(tag)

    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            while self.stack and self.stack[-1] != tag:
                self.errors.append(f'Unclosed: {self.stack.pop()}')
            if self.stack:
                self.stack.pop()

with open('/app/output/index.html') as f:
    html = f.read()

v = Validator()
v.feed(html)
if v.errors:
    print('Errors:', v.errors[:10])
if v.stack:
    print('Unclosed tags:', v.stack)
else:
    print('HTML structure OK')

# Check sections
sections = ['hero', 'team', 'work', 'cta-banner', 'services', 'insights', 'principles', 'footer']
for s in sections:
    if f'id=\"{s}\"' in html:
        print(f'  Section: {s} OK')
    else:
        print(f'  Section: {s} MISSING')

# Check interactions
interactions = ['heroTrack', 'teamCarousel', 'langSelector', 'cookieBanner', 'cookieModal', 'workScroll']
for i in interactions:
    if i in html:
        print(f'  Interaction: {i} OK')
    else:
        print(f'  Interaction: {i} MISSING')
